#!/usr/bin/env bash
# Generated by gitopsify. Applies the uat environment in reconciliation order:
# manifests with kubectl server-side apply, Helm releases with helm upgrade
# --install. Platform apps (CRDs, operators, webhooks) are waited for before the
# apps that need them.
#
#   ./apply-uat.sh [--context NAME] [--kubeconfig FILE] [--dry-run] [kubectl flags...]
#
# Needs kubectl (or kustomize) and, for Helm apps, helm 3 or 4.
set -euo pipefail
cd "$(dirname "$0")"

kubectl_args=()
helm_args=()
dry_run=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --context) kubectl_args+=(--context "$2"); helm_args+=(--kube-context "$2"); shift 2 ;;
    --context=*) kubectl_args+=("$1"); helm_args+=(--kube-context "${1#*=}"); shift ;;
    --kubeconfig) kubectl_args+=(--kubeconfig "$2"); helm_args+=(--kubeconfig "$2"); shift 2 ;;
    --kubeconfig=*) kubectl_args+=("$1"); helm_args+=("$1"); shift ;;
    --dry-run) dry_run=1; shift ;;
    *) kubectl_args+=("$1"); shift ;;
  esac
done

k() { kubectl ${kubectl_args[@]+"${kubectl_args[@]}"} "$@"; }
h() { helm ${helm_args[@]+"${helm_args[@]}"} "$@"; }

build() {
  if command -v kustomize >/dev/null 2>&1; then
    kustomize build "$1"
  else
    kubectl kustomize "$1"
  fi
}

# apply DIR: builds a Kustomization and server-side applies it.
apply() {
  echo ">> $1"
  build "$1" | k apply --server-side --field-manager=gitopsify --force-conflicts ${dry_run:+--dry-run=server} -f -
}

# apply_helm DIR RELEASE NAMESPACE CHART [helm flags...]: installs or upgrades
# a release with the values in DIR.
apply_helm() {
  local dir=$1 release=$2 namespace=$3 chart=$4
  shift 4
  echo ">> ${dir} (Helm release ${namespace}/${release})"
  h upgrade --install "${release}" "${chart}" --namespace "${namespace}" --create-namespace \
    -f "${dir}/values.yaml" ${dry_run:+--dry-run=server} "$@"
}

# wait_crds and wait_available let CRDs and the Deployments of operators and
# webhooks become ready before the apps that use them.
wait_crds() {
  [[ -n "${dry_run}" ]] || k wait --for=condition=Established crd --all --timeout=120s
}

wait_available() {
  [[ -n "${dry_run}" ]] || k wait --for=condition=Available deployment --all -n "$1" --timeout=300s
}

# wave -30
apply apps/crds/envs/uat
wait_crds

# wave -20
apply apps/namespaces/envs/uat

# wave -10
apply apps/cluster/envs/uat

# wave 0
apply_helm apps/inhouse/envs/uat inhouse tools ./apps/inhouse/charts/inhouse
apply apps/payments/envs/uat
apply_helm apps/podinfo/envs/uat podinfo podinfo podinfo --repo https://stefanprodan.github.io/podinfo --version 6.9.2
apply apps/shop/envs/uat
